    private static readonly Dictionary<string, SettingDefinition> ById = Rows.ToDictionary(r => r.Id, StringComparer.Ordinal);

    public IReadOnlyList<SettingDefinition> All => Rows;
    public SettingDefinition? Find(string id) => id is not null && ById.TryGetValue(id, out var d) ? d : null;
